import{_ as s,a0 as i,w as p,s as d,ao as l,I as n,x as t,a1 as a,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"了解如何使用 Norka 编辑器阅读文本 | LCTT x X-CMD","titleTemplate":false,"description":"了解如何使用 Norka 编辑器阅读文本 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"了解如何使用 Norka 编辑器阅读文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"了解如何使用 Norka 编辑器阅读文本 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201218 Find out how your text will be read with Norka","title":"了解如何使用 Norka 编辑器阅读文本","tag":"202012","desc":""},"relativePath":"202012/20201218 Find out how your text will be read with Norka.md","filePath":"[post].md"}'),k={name:"202012/20201218 Find out how your text will be read with Norka.md"};function u(m,o,N,f,T,h){const r=i("Link");return p(),d("div",null,[o[23]||(o[23]=l('<h1 id="了解如何使用-norka-编辑器阅读文本" tabindex="-1">了解如何使用 Norka 编辑器阅读文本 <a class="header-anchor" href="#了解如何使用-norka-编辑器阅读文本" aria-label="Permalink to “了解如何使用 Norka 编辑器阅读文本”">​</a></h1><blockquote><p>这是一个素颜朝天的文本编辑器，旨在让你的写作能被更好地阅读和理解。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/28/003505f3h3pppkg7enpxi9.jpg" alt=""></p><p>有些文本编辑器是为编程而设计的，有些是为专门的文本格式而设计的，有些是为文档设计而设计的。Norka 文本编辑器是为阅读而设计的。创建一个为<em>阅读</em>而设计的文本编辑器似乎很奇怪，但实际上，如果你仔细想想，这是很有意义的。你的文字已经写了一次或三次，这取决于你个人对迭代的容忍度，但它的目的是为了在未来几年内被阅读。Norka 让你轻松地专注于你的文字如何被阅读。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3>',5)),n("p",null,[o[2]||(o[2]=t("Norka 文本编辑器是 MIT 授权的，可以",-1)),a(r,{href:"https://flathub.org/apps/details/com.github.tenderowl.norka"},{default:e(()=>[...o[0]||(o[0]=[t("作为 Flatpak 包安装在 Linux上",-1)])]),_:1}),o[3]||(o[3]=t("。它是开源的，所以如果你想尝试在不同的平台上安装它，你可以",-1)),a(r,{href:"https://github.com/TenderOwl/Norka"},{default:e(()=>[...o[1]||(o[1]=[t("克隆它的 Github 仓库",-1)])]),_:1}),o[4]||(o[4]=t("。",-1))]),o[24]||(o[24]=l('<h3 id="norka-的界面" tabindex="-1">Norka 的界面 <a class="header-anchor" href="#norka-的界面" aria-label="Permalink to “Norka 的界面”">​</a></h3><p>Norka 的界面很简单。一个回到 Norka 文档集的按钮，一个导出按钮和一个偏好菜单。窗口的其余部分是供你写文字的空白空间，在右下角，有一个阅读时间计算器来帮助你了解读者可能需要多长时间才能看完你写的东西。</p><p><img src="https://opensource.com/sites/default/files/uploads/norka-31_days-norka-opensource.png" alt="Dark Norka terminal box with green and white text" title="Dark Norka terminal box with green and white text"></p><p>这几乎就是 Norka 的全部内容。没有分页符或行号，没有代码折叠或正则搜索。这是一个用于文字书写的编辑器，而不设置文档样式或跟踪复杂的数据模式。</p><p>当然，它还有一些额外的功能。如预期那样，可以使用 <code>Ctrl+C</code> 和 <code>Ctrl+V</code> 复制和粘贴。你可以用 <code>Ctrl+Z</code> 撤销，用 <code>Ctrl+F</code> 查找。你甚至可以用 <code>Ctrl+:</code> 插入表情符号。</p><p><img src="https://opensource.com/sites/default/files/uploads/norka_emoji-31_days-norka-opensource.png" alt="Norka terminal box with pop up box of emoji search menu" title="Norka terminal box with pop up box of emoji search menu"></p><h4 id="样式文本" tabindex="-1">样式文本 <a class="header-anchor" href="#样式文本" aria-label="Permalink to “样式文本”">​</a></h4>',7)),n("p",null,[o[6]||(o[6]=t("虽然 Norka 绝对没有兴趣帮你设计，比如说，一本小册子或传单，但它确实有一些能力来指示你想要的文本样式。它通过 ",-1)),a(r,{href:"https://opensource.com/article/19/9/introduction-markdown"},{default:e(()=>[...o[5]||(o[5]=[t("Markdown",-1)])]),_:1}),o[7]||(o[7]=t(" 来实现这一点，这是一个简单的纯文本书写的约定，但用特殊的符号来指示文本应该如何在 HTML、EPUB 或 PDF 或任何你的目标格式中呈现。",-1))]),o[25]||(o[25]=l('<p>在大多数编辑器中，你必须知道 Markdown 才能使用 Markdown，但 Norka 翻译了常见的文字处理器键盘快捷键来为你生成 Markdown。例如，要使一个单词加粗，你可以按 <code>Ctrl+B</code>，它会在光标的两边插入四个星号。当你输入下一个单词时，它的两边都会有两个星号，这就是 Markdown 对粗体（默认为粗体）文本的标记。你可以在 Norka 窗口右上角的汉堡样式的菜单中查看所有的 Markdown 快捷方式。</p><h4 id="保存和导出" tabindex="-1">保存和导出 <a class="header-anchor" href="#保存和导出" aria-label="Permalink to “保存和导出”">​</a></h4><p>你可以把 Norka 想象成一个笔记本。你在 Norka 中打开的所有文档都会保留在 Norka 的内部数据库中，所有的文档都会默认自动保存。要在 Norka 外使用文件，你可以在打开的文件中点击右上角的<strong>共享</strong>按钮。另外，你也可以在 Norka 的文件视图中右击任何文件，选择<strong>导出</strong>。你可以将文档导出（或<strong>共享</strong>，Norka 可互换使用这两个术语）为<strong>文本</strong>、<strong>HTML</strong> 或 <strong>Markdown</strong>。</p><h3 id="尝试-norka" tabindex="-1">尝试 Norka <a class="header-anchor" href="#尝试-norka" aria-label="Permalink to “尝试 Norka”">​</a></h3><p>Norka 便于尝试，也易于使用。它通过保持界面简单，几乎到了受限的程度，帮助你专注于写作。但限制有时也是一种强大的创意工具。</p><p>Norka 可能不是你进行大量修改或文本处理的最佳选择。它没有让人激动的功能，比如大小写转换、集成 <code>sed</code> 命令、字符交换等等。它是一个为读者服务的文本编辑器。如果你觉得有用，那么你可能正是 Norka 正在寻找的受众。</p><p>感谢你花 2 分 39 秒阅读本文！</p><hr>',8)),n("p",null,[o[9]||(o[9]=t("via: ",-1)),a(r,{href:"https://opensource.com/article/20/12/norka"},{default:e(()=>[...o[8]||(o[8]=[t("https://opensource.com/article/20/12/norka",-1)])]),_:1})]),n("p",null,[o[14]||(o[14]=t("作者：",-1)),a(r,{href:"https://opensource.com/users/seth"},{default:e(()=>[...o[10]||(o[10]=[t("Seth Kenlon",-1)])]),_:1}),o[15]||(o[15]=t(" 选题：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:e(()=>[...o[11]||(o[11]=[t("lujun9972",-1)])]),_:1}),o[16]||(o[16]=t(" 译者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:e(()=>[...o[12]||(o[12]=[t("geekpi",-1)])]),_:1}),o[17]||(o[17]=t(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:e(()=>[...o[13]||(o[13]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[20]||(o[20]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...o[18]||(o[18]=[t("LCTT",-1)])]),_:1}),o[21]||(o[21]=t(" 原创编译，",-1)),a(r,{href:"https://linux.cn/"},{default:e(()=>[...o[19]||(o[19]=[t("Linux中国",-1)])]),_:1}),o[22]||(o[22]=t(" 荣誉推出",-1))])])}const w=s(k,[["render",u]]);export{b as __pageData,w as default};
